import javax.tools.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

/**
 * Tiny build bootstrap. The container ships a JRE that still contains the
 * jdk.compiler module but no javac launcher, so we drive the compiler through
 * its public API instead.
 *
 *   java Boot.java <srcDir> <outDir>
 */
public class Boot {
    public static void main(String[] args) throws Exception {
        Path src = Paths.get(args[0]);
        Path out = Paths.get(args[1]);
        Files.createDirectories(out);
        List<String> files;
        try (Stream<Path> s = Files.walk(src)) {
            files = s.filter(p -> p.toString().endsWith(".java"))
                     .map(Path::toString)
                     .sorted()
                     .collect(Collectors.toList());
        }
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            System.err.println("no java compiler available");
            System.exit(2);
        }
        List<String> argv = new ArrayList<>();
        argv.add("-d");
        argv.add(out.toString());
        argv.add("-encoding");
        argv.add("UTF-8");
        argv.addAll(files);
        int rc = compiler.run(null, null, null, argv.toArray(new String[0]));
        System.exit(rc);
    }
}

