package ditaa;

/** A position in the character grid. */
public final class Cell implements Comparable<Cell> {
    public final int x;
    public final int y;

    public Cell(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public Cell(Cell other) {
        this(other.x, other.y);
    }

    public Cell north() { return new Cell(x, y - 1); }
    public Cell south() { return new Cell(x, y + 1); }
    public Cell east()  { return new Cell(x + 1, y); }
    public Cell west()  { return new Cell(x - 1, y); }

    public Cell nw() { return new Cell(x - 1, y - 1); }
    public Cell ne() { return new Cell(x + 1, y - 1); }
    public Cell sw() { return new Cell(x - 1, y + 1); }
    public Cell se() { return new Cell(x + 1, y + 1); }

    public boolean isNextTo(Cell c) {
        int dx = Math.abs(x - c.x);
        int dy = Math.abs(y - c.y);
        return dx + dy == 1;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Cell)) return false;
        Cell c = (Cell) o;
        return c.x == x && c.y == y;
    }

    @Override
    public int hashCode() {
        return x * 31 + y;
    }

    @Override
    public int compareTo(Cell o) {
        if (y != o.y) return Integer.compare(y, o.y);
        return Integer.compare(x, o.x);
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ")";
    }
}

